def compute(vars):
    less_than_50000 = {
        "2019": vars["v1"] < 50000,
        "2018": vars["v2"] < 50000,
    }
    year = next((year for year, is_less in less_than_50000.items() if is_less), None)
    return {
        "value": year,
        "trace": {
            "less_than_50000": less_than_50000,
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
